impl fmt::Display for CountryCode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl AsRef<str> for CountryCode {
    fn as_ref(&self) -> &str {
        self.as_str()
    }
}

impl TryFrom<&str> for CountryCode {
    type Error = MollieError;
    fn try_from(value: &str) -> Result<Self, Self::Error> {
        Self::parse(value)
    }
}

impl TryFrom<String> for CountryCode {
    type Error = MollieError;
    fn try_from(value: String) -> Result<Self, Self::Error> {
        Self::parse(value)
    }
}

impl From<CountryCode> for String {
    fn from(value: CountryCode) -> Self {
        value.as_str().to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::CountryCode;

    #[test]
    fn parse_round_trips_all_codes() {
        assert_eq!(CountryCode::ALL.len(), 250);
        for code in CountryCode::ALL {
            let again = CountryCode::parse(code.as_str()).unwrap();
            assert_eq!(again, code);
            assert_eq!(again.to_string().len(), 2);
            assert!(!code.name().is_empty());
        }
    }

    #[test]
    fn official_names_and_subdivisions_samples() {
        assert_eq!(CountryCode::NL.name(), "Netherlands, Kingdom of the");
        assert_eq!(
            CountryCode::GB.name(),
            "United Kingdom of Great Britain and Northern Ireland"
        );
        assert_eq!(CountryCode::BO.name(), "Bolivia, Plurinational State of");
        assert_eq!(CountryCode::AD.subdivisions(), Some("7 parishes"));
        assert_eq!(CountryCode::AQ.subdivisions(), None);
        assert!(CountryCode::is_valid("AN")); // historical
    }

    #[test]
    fn rejects_invalid() {
        assert!(CountryCode::parse("nl").is_err());
        assert!(CountryCode::parse("NLD").is_err());
        assert!(CountryCode::parse("XX").is_err());
        assert!(CountryCode::parse("").is_err());
        assert!(CountryCode::is_valid_format("XX"));
        assert!(!CountryCode::is_valid("XX"));
    }
}
